  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum UserRole {\n  STUDENT\n  EMPLOYER\n  ADMIN\n  SUPER_ADMIN\n}\n\nenum UserStatus {\n  PENDING\n  ACTIVE\n  SUSPENDED\n  INACTIVE\n}\n\nenum ApplicationStatus {\n  PENDING\n  IN_PROGRESS\n  COMPLETED\n  REJECTED\n}\n\nenum VisaStatus {\n  NOT_STARTED\n  DOCUMENTS_SUBMITTED\n  APPOINTMENT_SCHEDULED\n  INTERVIEW_COMPLETED\n  VISA_GRANTED\n  VISA_REJECTED\n}\n\nenum PaymentStatus {\n  PENDING\n  PROCESSING\n  COMPLETED\n  FAILED\n}\n\nmodel User {\n  id        String     @id @default(uuid())\n  email     String     @unique\n  password  String\n  role      UserRole\n  status    UserStatus @default(PENDING)\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  // Profile relations based on role\n  student    Student?\n  employer   Employer?\n  admin      Admin?\n  superAdmin SuperAdmin?\n\n  // Common relations\n  chatMessages  ChatMessage[]\n  notifications Notification[]\n\n  @@map(\"users\")\n}\n\nmodel Student {\n  id               String   @id @default(uuid())\n  userId           String   @unique\n  user             User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  applicationId    String   @unique\n  firstName        String\n  lastName         String\n  dateOfBirth      DateTime\n  nationality      String\n  phone            String?\n  address          String?\n  currentEducation String?\n  referralCode     String?  @unique\n  referredBy       String?\n\n  // Relations\n  documents        Document[]\n  applications     Application[]\n  visaApplications VisaApplication[]\n  payments         Payment[]\n  testimonial      Testimonial?\n  universityOffers UniversityOffer[]\n\n  @@map(\"students\")\n}\n\nmodel Employer {\n  id                 String  @id @default(uuid())\n  userId             String  @unique\n  user               User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  companyName        String\n  registrationNumber String  @unique\n  companySize        Int?\n  industry           String?\n  website            String?\n  address            String\n  phone              String\n  verificationDoc    String? // URL to CAC/UK document\n\n  // Relations\n  recruitmentRequests RecruitmentRequest[]\n  jobPostings         JobPosting[]\n  payments            Payment[]\n\n  @@map(\"employers\")\n}\n\nmodel Admin {\n  id           String @id @default(uuid())\n  userId       String @unique\n  user         User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  firstName    String\n  lastName     String\n  department   String\n  assignedRole String // e.g., \"student_management\", \"employer_management\"\n\n  @@map(\"admins\")\n}\n\nmodel SuperAdmin {\n  id        String @id @default(uuid())\n  userId    String @unique\n  user      User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  firstName String\n  lastName  String\n\n  @@map(\"super_admins\")\n}\n\nmodel Application {\n  id         String            @id @default(uuid())\n  studentId  String\n  student    Student           @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  status     ApplicationStatus @default(PENDING)\n  program    String\n  university String\n  intake     DateTime\n  createdAt  DateTime          @default(now())\n  updatedAt  DateTime          @updatedAt\n\n  // Relations\n  documents Document[]\n\n  @@map(\"applications\")\n}\n\nmodel VisaApplication {\n  id              String     @id @default(uuid())\n  studentId       String\n  student         Student    @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  status          VisaStatus @default(NOT_STARTED)\n  country         String\n  appointmentDate DateTime?\n  documents       Document[]\n  notes           String?\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n\n  @@map(\"visa_applications\")\n}\n\nmodel Document {\n  id                String           @id @default(uuid())\n  name              String\n  type              String // e.g., \"passport\", \"transcript\", \"offer_letter\"\n  url               String // Cloudinary URL\n  studentId         String\n  student           Student          @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  applicationId     String?\n  application       Application?     @relation(fields: [applicationId], references: [id])\n  visaApplicationId String?\n  visaApplication   VisaApplication? @relation(fields: [visaApplicationId], references: [id])\n  uploadedAt        DateTime         @default(now())\n\n  @@map(\"documents\")\n}\n\nmodel UniversityOffer {\n  id          String    @id @default(uuid())\n  studentId   String\n  student     Student   @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  university  String\n  program     String\n  offerLetter String // URL to offer letter\n  status      String // \"pending\", \"accepted\", \"rejected\"\n  createdAt   DateTime  @default(now())\n  respondedAt DateTime?\n\n  @@map(\"university_offers\")\n}\n\nmodel RecruitmentRequest {\n  id           String   @id @default(uuid())\n  employerId   String\n  employer     Employer @relation(fields: [employerId], references: [id], onDelete: Cascade)\n  type         String // \"PRN\", \"One-Time\", \"Outsourcing\"\n  jobTitle     String\n  description  String\n  requirements String[]\n  budget       Float\n  deadline     DateTime\n  status       String // \"pending\", \"in_progress\", \"completed\"\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@map(\"recruitment_requests\")\n}\n\nmodel JobPosting {\n  id           String   @id @default(uuid())\n  employerId   String\n  employer     Employer @relation(fields: [employerId], references: [id], onDelete: Cascade)\n  title        String\n  description  String\n  requirements String[]\n  location     String\n  type         String // \"full-time\", \"part-time\", \"contract\"\n  salary       Float?\n  createdAt    DateTime @default(now())\n  deadline     DateTime\n  status       String // \"open\", \"closed\"\n\n  @@map(\"job_postings\")\n}\n\nmodel Payment {\n  id          String        @id @default(uuid())\n  amount      Float\n  currency    String        @default(\"NGN\")\n  status      PaymentStatus @default(PENDING)\n  type        String // \"service_fee\", \"recruitment_fee\"\n  reference   String        @unique\n  studentId   String?\n  student     Student?      @relation(fields: [studentId], references: [id])\n  employerId  String?\n  employer    Employer?     @relation(fields: [employerId], references: [id])\n  metadata    Json?\n  paymentDate DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  @@map(\"payments\")\n}\n\nmodel ChatMessage {\n  id        String   @id @default(uuid())\n  content   String\n  senderId  String\n  sender    User     @relation(fields: [senderId], references: [id], onDelete: Cascade)\n  roomId    String\n  createdAt DateTime @default(now())\n\n  @@map(\"chat_messages\")\n}\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title     String\n  message   String\n  type      String // \"info\", \"success\", \"warning\", \"error\"\n  isRead    Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@map(\"notifications\")\n}\n\nmodel Testimonial {\n  id         String   @id @default(uuid())\n  studentId  String   @unique\n  student    Student  @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  content    String\n  rating     Int\n  videoUrl   String? // Cloudinary URL\n  isApproved Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@map(\"testimonials\")\n}\n",
